using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using McpApiServer.Tools;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddHttpClient("ApiClient", client =>
    {
        client.BaseAddress = new Uri("https://jsonplaceholder.typicode.com");
        client.DefaultRequestHeaders.Add("Accept", "application/json");
    });

builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new()
        {
            Name = "api-tools-server",
            Version = "1.0.0"
        };
    })
    .WithStdioServerTransport()
    .WithTools<ApiTools>();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpApiServer.Tools;

[McpServerToolType]
public sealed class ApiTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    // Constructor params are resolved from DI automatically.
    // The MCP SDK creates a new instance per tool invocation,
    // resolving constructor dependencies from the service provider.
    public ApiTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool(Name = "get_posts"), Description("Get all posts, optionally filtered by user ID.")]
    public async Task<IEnumerable<Post>> GetPosts(
        [Description("Filter posts by this user ID. Omit to get all posts.")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("ApiClient");

        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        return await client.GetFromJsonAsync<List<Post>>(url, cancellationToken) ?? [];
    }

    [McpServerTool(Name = "get_post"), Description("Get a single post by its ID.")]
    public async Task<Post?> GetPost(
        [Description("The numeric ID of the post to retrieve.")] int id,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("ApiClient");
        return await client.GetFromJsonAsync<Post>($"/posts/{id}", cancellationToken);
    }

    [McpServerTool(Name = "create_post"), Description("Create a new post.")]
    public async Task<Post?> CreatePost(
        [Description("The title of the post.")] string title,
        [Description("The body content of the post.")] string body,
        [Description("The user ID of the post author.")] int userId,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("ApiClient");

        var payload = new { title, body, userId };
        var response = await client.PostAsJsonAsync("/posts", payload, cancellationToken);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Post>(cancellationToken);
    }

    [McpServerTool(Name = "get_comments"), Description("Get comments for a specific post.")]
    public async Task<IEnumerable<Comment>> GetComments(
        [Description("The post ID to retrieve comments for.")] int postId,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("ApiClient");
        return await client.GetFromJsonAsync<List<Comment>>($"/posts/{postId}/comments", cancellationToken) ?? [];
    }
}

